private final Semaphore slots = new Semaphore(8, true);   // fair: FIFO, no starvation

void handle(Request r) throws InterruptedException {
    if (!slots.tryAcquire(250, TimeUnit.MILLISECONDS)) {
        r.reject();                    // bounded wait, explicit shedding
        return;
    }
    try { serve(r); } finally { slots.release(); }   // every exit path
}
